import openpyxl

# Read the original file (with formulas) to make a final check
wb = openpyxl.load_workbook('/root/test-supply.xlsx')
ws = wb['Production']

# Check that all required cells have formulas
issues = []

# B3: depreciation rate
if not ws.cell(3, 2).value:
    issues.append("B3 (depreciation rate) is empty")

# D6:D27, E6:E27: K and Y
for r in range(6, 28):
    if not ws.cell(r, 4).value:
        issues.append(f"D{r} (K) is empty")
    if not ws.cell(r, 5).value:
        issues.append(f"E{r} (Y) is empty")

# F6:F27, G6:G27: LnK, LnY
for r in range(6, 28):
    if not ws.cell(r, 6).value:
        issues.append(f"F{r} (LnK) is empty")
    if not ws.cell(r, 7).value:
        issues.append(f"G{r} (LnY) is empty")

# K6:K27: LnZ
for r in range(6, 28):
    if not ws.cell(r, 11).value:
        issues.append(f"K{r} (LnZ) is empty")

# L6:L27: LnZ_HP
for r in range(6, 28):
    if not ws.cell(r, 12).value:
        issues.append(f"L{r} (LnZ_HP) is empty")

# M7:M26: second-order difference  
for r in range(7, 27):
    if not ws.cell(r, 13).value:
        issues.append(f"M{r} (second-order diff) is empty")

# N6:N27: LnA-Trend check
for r in range(6, 28):
    if not ws.cell(r, 14).value:
        issues.append(f"N{r} (LnA-Trend check) is empty")

# P5: objective
if not ws.cell(5, 16).value:
    issues.append("P5 (objective) is empty")

# Lower section: 36-75
for r in range(36, 76):
    for c, name in [(4, 'K/Y'), (5, 'K'), (6, 'Y'), (7, 'LnZ trend'), (8, 'Ystar_base'), (11, 'K_With'), (12, 'Ystar_with'), (13, 'Uplift'), (14, 'Projected GDP')]:
        if not ws.cell(r, c).value:
            issues.append(f"{name} at row {r} (year {ws.cell(r, 3).value}) is empty")

# Growth rates (rows 37-75)
for r in range(37, 76):
    for c, name in [(15, 'Proj GDP Growth'), (16, 'Baseline GDP Growth')]:
        if not ws.cell(r, c).value:
            issues.append(f"{name} at row {r} is empty")

# Investment (rows 60-67, years 2026-2033)
for r in range(60, 68):
    if not ws.cell(r, 9).value:
        issues.append(f"Investment at row {r} is empty")

# deltaK (rows 60-75)
for r in range(60, 76):
    if not ws.cell(r, 10).value:
        issues.append(f"deltaK at row {r} is empty")

if issues:
    print("ISSUES FOUND:")
    for i in issues:
        print(f"  - {i}")
else:
    print("All required cells are populated!")

# Also check WEO sheet
ws_weo = wb['WEO_Data']
weo_issues = []
for r in range(8, 52):
    if not ws_weo.cell(r, 3).value:
        weo_issues.append(f"WEO C{r} (GDP level for {ws_weo.cell(r,2).value}) is empty")
    if not ws_weo.cell(r, 4).value:
        weo_issues.append(f"WEO D{r} (GDP growth for {ws_weo.cell(r,2).value}) is empty")

if weo_issues:
    print("\nWEO ISSUES:")
    for i in weo_issues:
        print(f"  - {i}")
else:
    print("WEO sheet complete!")

# Check CFC sheet
ws_cfc = wb['CFC data']
cfc_issues = []
for r in range(2, 30):
    if not ws_cfc.cell(r, 3).value:
        cfc_issues.append(f"CFC C{r} is empty")
    if not ws_cfc.cell(r, 4).value:
        cfc_issues.append(f"CFC D{r} (Capital Stock) is empty")
    if not ws_cfc.cell(r, 5).value:
        cfc_issues.append(f"CFC E{r} (Dep rate) is empty")

if cfc_issues:
    print("\nCFC ISSUES:")
    for i in cfc_issues:
        print(f"  - {i}")
else:
    print("CFC data sheet complete!")

# Check PWT sheet
ws_pwt = wb['PWT']
pwt_issues = []
for r in range(2, 36):
    if not ws_pwt.cell(r, 2).value:
        pwt_issues.append(f"PWT B{r} (year {ws_pwt.cell(r,1).value}) is empty")
if pwt_issues:
    print("\nPWT ISSUES:")
    for i in pwt_issues:
        print(f"  - {i}")
else:
    print("PWT sheet complete!")
